def atbit(op, bit):
    out = s.zeros(8)
    for state in range(8):
        b = state >> bit & 1
        if op == 'n':
            out[state, state] = b
        elif op == 'X':
            out[state ^ 1 << bit, state] = 1
        elif op == 'Y':
            out[state ^ 1 << bit, state] = I * (1 - 2 * b)
    return out

